+/**
+ * Safely evaluate a JavaScript expression using a sandboxed context.
+ * This prevents arbitrary code execution by restricting access to global objects.
+ */
+export const safeEval = (code: string): any => {
+  // Use vm module in Node.js to create an isolated context.
+  if (typeof process !== 'undefined' && process.versions && process.versions.node) {
+    // eslint-disable-next-line @typescript-eslint/no-var-requires
+    const vm = require('vm');
+    const sandbox = Object.create(null);
+    return vm.runInNewContext('(' + code + ')', sandbox, { timeout: 100 });
+  }
+  // In browser environments, evaluating arbitrary code is not allowed.
+  throw new Error('Dynamic code evaluation is disabled for security reasons');
+};
